export function getFolderZone(folder: any): RepoZoneId {
  if (!folder) return "green";
  if (folder.zone === "green" || folder.zone === "yellow" || folder.zone === "purple" || folder.zone === "black") {
    return folder.zone;
  }
  const c = (folder.color || "").toLowerCase();
  if (c.includes("10b981") || c.includes("059669") || c.includes("emerald") || c.includes("green") || c.includes("43a047") || c.includes("16a34a") || c.includes("00897b")) return "green";
  if (c.includes("f59e0b") || c.includes("d97706") || c.includes("amber") || c.includes("yellow") || c.includes("f14b04") || c.includes("e65100") || c.includes("ea580c") || c.includes("fb8c00") || c.includes("e7f613")) return "yellow";
  if (c.includes("a855f7") || c.includes("8e24aa") || c.includes("purple") || c.includes("violet") || c.includes("d81b60") || c.includes("9333ea") || c.includes("e11d48")) return "purple";
  if (c.includes("09090b") || c.includes("black") || c.includes("1e293b") || c.includes("0284c7") || c.includes("1e88e5") || c.includes("2563eb") || c.includes("475569") || c.includes("546e7a") || c.includes("slate") || c.includes("blue")) return "black";
  return "green";
}

export function getFirstGreenFolder(folders: any[]): string | null {
  if (!Array.isArray(folders) || folders.length === 0) return null;
  const activeFolders = folders.filter((f) => !f.isFolderHidden && f.id !== "all-favorites");
  if (activeFolders.length === 0) return null;
  const firstGreen = activeFolders.find((f) => getFolderZone(f) === "green");
  return firstGreen ? firstGreen.id : activeFolders[0].id;
}

export function getRepoZoneConfig(zoneId: string): RepoZoneConfig {
  return REPO_ZONES.find((z) => z.id === zoneId) || REPO_ZONES[0];
}
